# Reject any place whose country is absent from countries.py.
_VALID_COUNTRIES: set[str] = {c["name"] for c in _COUNTRIES}
# A place's country must also match its city's country in cities.py.
_COUNTRY_BY_CITY: dict[str, str] = {c["name"]: c["country"] for c in _CITIES}
for _place in PLACES:
    if _place["country"] not in _VALID_COUNTRIES:
        raise ValueError(
            f"places.py: {_place['name']!r} uses unknown country "
            f"{_place['country']!r} — add it to app/data/countries.py"
        )
    _city = _place["city"]
    if _city not in _COUNTRY_BY_CITY:
        raise ValueError(
            f"places.py: {_place['name']!r} references unknown city "
            f"{_city!r} — add it to app/data/cities.py"
        )
    if _place["country"] != _COUNTRY_BY_CITY[_city]:
        raise ValueError(
            f"places.py: {_place['name']!r} in {_city!r} has country "
            f"{_place['country']!r} but cities.py says "
            f"{_COUNTRY_BY_CITY[_city]!r}"
        )

# Enforce the invariant that every city has ≥3 places at import time.
_MIN_PLACES_PER_CITY = 3
_PLACE_COUNTS: dict[str, int] = {}
for _place in PLACES:
    _PLACE_COUNTS[_place["city"]] = _PLACE_COUNTS.get(_place["city"], 0) + 1
_short = {
    c["name"]: _PLACE_COUNTS.get(c["name"], 0)
    for c in _CITIES
    if _PLACE_COUNTS.get(c["name"], 0) < _MIN_PLACES_PER_CITY
}
if _short:
    raise ValueError(
        f"places.py: every city in cities.py must have ≥{_MIN_PLACES_PER_CITY} "
        f"places (CLAUDE.md invariant). Short cities: {_short}"
    )
